contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, address target) public payable {
        require(target != address(0));
        require(target != address(c));
        require(address(this).balance >= amount);

        uint cBefore = address(c).balance;
        uint tBefore = target.balance;

        bool sendReverted;
        try c.sendMoney{value: amount}(target, amount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        if (!sendReverted) {
            assert(address(c).balance == cBefore - amount);
            assert(target.balance == tBefore + amount);
        } else {
            assert(address(c).balance == cBefore);
            assert(target.balance == tBefore);
        }
    }

    receive() external payable {}
}

