contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint value) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Fund c via its fallback so its balance can be observed before and after the unauthorized calls.
        (bool fundOk, ) = address(c).call{value: amount}("");
        require(fundOk, "funding fallback failed");

        uint balanceBefore = address(c).balance;

        // Try the three owner-only state-changing functions as a non-owner.
        // The current msg.sender for c's calls is this test contract.
        // First, make sure the test contract is not C's owner by construction: C's owner is msg.sender
        // at deployment, which is whoever deployed C (the checker), not this test contract.

        bool withdrawReverted;
        try c.withdraw(value) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(address(this), value) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        assert(
            withdrawReverted && withdrawAllReverted && sendMoneyReverted && address(c).balance == balanceBefore
        );
    }

    receive() external payable {}
}

