        c.sendMoney(target, sendAmount);
        uint256 depositsAfterSend = c.depositsCount();

        assert(
            depositsAfterDeposit == depositsBefore + 1 &&
            balanceAfterDeposit == balanceBefore + depositAmount &&
            depositsAfterWithdrawAll == depositsAfterDeposit &&
            depositsAfterWithdraw == depositsAfterDeposit &&
            depositsAfterSend == depositsAfterDeposit
        );
    }
}

