contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller, uint value) public payable {
        require(address(this).balance >= value, "not enough balance");
        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount();
        bool wAllReverted;
        bool wReverted;
        bool sReverted;

        // Ensure caller is not the owner, so ownership checks must fail.
        // The owner is the address that deployed C, which is address(this) in this test.
        require(caller != address(this));

        // Use a low-level call from the test contract to have msg.sender = caller
        // for the calls on c.  This is allowed because the test directly drives c,
        // and the caller is just a parameter.
        // We wrap each restricted function call in try/catch via low-level call.

        // withdrawAll
        (bool ok1, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        wAllReverted = !ok1;

        // withdraw
        (bool ok2, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", value));
        wReverted = !ok2;

        // sendMoney to this test contract with value; should also revert
        (bool ok3, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", address(this), value));
        sReverted = !ok3;

        // State must be unchanged because all owner-only calls reverted.
        assert(wAllReverted && wReverted && sReverted &&
               address(c).balance == balBefore &&
               c.depositsCount() == countBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint public callbackCount;

    constructor(C _c) { c = _c; }

    receive() external payable {
        callbackCount++;
    }

    function run(address target, uint value, bool makeTargetRevert) public payable {
        require(address(this).balance >= value, "not enough balance");

        // Deploy is done by this test contract, so this test contract is the owner of C.
        // Ensure the target is not C or this test contract to avoid confusing callbacks.
        require(target != address(c));
        require(target != address(this));

        uint countBefore = c.depositsCount();
        uint targetBalanceBefore = target.balance;
        uint cBalanceBefore = address(c).balance;

        bool sendReverted;
        // Setup: if makeTargetRevert is requested by the caller of run, deploy a tiny
        // reverting contract via assembly is not allowed, so we rely on the target
        // being a plain address (EOA) or a contract that receives Ether; the external
        // call will succeed whenever target is a simple account or a non-reverting contract.
        try c.sendMoney{value: value}(target, value) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint countAfter = c.depositsCount();
        uint targetBalanceAfter = target.balance;
        uint cBalanceAfter = address(c).balance;

        // General rule: if the send succeeds, the target received exactly value, C balance
        // decreased by exactly value, and depositsCount is unchanged unless the target's
        // fallback re-entered C (observable as an extra deposit). In the normal case
        // where target is a non-contract or a non-reentering contract, depositsCount stays
        // the same. If send reverts, balances and count are unchanged.
        if (sendReverted) {
            assert(cBalanceAfter == cBalanceBefore && countAfter == countBefore);
        } else {
            assert(targetBalanceAfter == targetBalanceBefore + value);
            assert(cBalanceAfter + value == cBalanceBefore);
            assert(countAfter >= countBefore);
            // If target's fallback executed and sent Ether to C, count could increase.
            // The non-degenerate case: target is not a contract that calls C.
            assert(target == address(c) || targetBalanceAfter - targetBalanceBefore == value);
        }
    }
}

